    if (tmp == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Initialize L
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            L[i * n + j] = 0.0;
        }
    }

    // Compute the diagonal elements of L
    for (int i = 0; i < n; i++) {
        L[i * n + i] = kernel_cholesky(n, A, L);
    }

    // Store the scaling factors for the rows
    for (int i = 0; i < n; i++) {
        p[i] = 1.0 / sqrt(L[i * n + i]);
    }

