    #pragma omp parallel private (t, i, j)
    {
        for (t = 0; t < _PB_TSTEPS; t++) {
            #pragma omp for nowait
            for (j = 0; j < _PB_NY; j++) {
                ey[0][j] = _fict_[t];
            }

            #pragma omp for collapse(2) nowait schedule(static)
            for (i = 1; i < _PB_NX; i++) {
                for (j = 0; j < _PB_NY; j++) {
                    ey[i][j] = ey[i][j] - 0.5*(hz[i][j]-hz[i-1][j]);
                }
