void kernel_ludcmp(int n, DATA_TYPE POLYBENCH_2D(A, N+1, N+1, n+1, n+1), DATA_TYPE POLYBENCH_1D(b, N+1, n+1), DATA_TYPE POLYBENCH_1D(x, N+1, n+1), DATA_TYPE POLYBENCH_1D(y, N+1, n+1)) {
