    b[0] = 1.0;

    // Create a separate array to store the sums for each thread
    DATA_TYPE* sums = (DATA_TYPE*)malloc(n * sizeof(DATA_TYPE));
    if (sums == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Parallelize the LU decomposition
    #pragma omp parallel for
    for (int i = 0; i < n; i++) {
        // Calculate the elements of the matrix A below the diagonal
        DATA_TYPE w = A[i][i] - (sums[i] = 0); // Sum of products from previous columns

        // Update the first half of the matrix
        for (int j = 0; j < i; j++) {
            A[j][i] -= w;
        }

        // Barrier to synchronize the threads
        #pragma omp barrier

        // Update the current row of matrix A
        for (int j = i + 1; j < n; j++) {
            A[j][i] -= w;
        }
    }

    // Compute the solution for intermediate vector y
    for (int i = 0; i < n; i++) {
        y[i] = b[i];
    }

    // Back-substitution
    for (int i = n - 1; i >= 0; i--) {
        DATA_TYPE x_i = y[i];
        for (int j = i + 1; j < n; j++) {
            x_i -= A[i][j] * x_j;
        }
        x[i] /= A[i][i];
    }

    // Free the allocated memory
    free(sums);
}

